import 'dart:convert';
import 'dart:typed_data';
import '../models/forwarder_config.dart';
import 'nca_builder.dart';
import 'pfs0_builder.dart';
import 'romfs_builder.dart';

/// Audited compiled ARM64 Nintendo Switch Homebrew Forwarder Payload & NPDM Template.
///
/// Wraps the standard ARM64 forwarder binary stub ('main' executable in NSO0 format)
/// and Nintendo Process Descriptor Meta ('main.npdm') with ACID/ACI0 capabilities.
/// Supports embedding target NRO / ROM redirection paths via Program RomFS.
class ForwarderStubTemplate {
  /// Base64-encoded compiled ARM64 NSO0 forwarder binary (53,149 bytes).
  static const String _rawMainBase64 =
      '';

  /// Base64-encoded valid process descriptor metadata (1,016 bytes).
  static const String _rawNpdmBase64 =
      '';

  /// Returns the unpatched ARM64 forwarder executable binary.
  static Uint8List getMainBinary() {
    return base64Decode(_rawMainBase64);
  }

  /// Returns the process descriptor metadata (main.npdm) patched with [titleIdHex].
  static Uint8List getPatchedNpdm(String titleIdHex) {
    final Uint8List npdm = base64Decode(_rawNpdmBase64);
    final normalized = NcaBuilder.parseTitleId(titleIdHex);
    final cleanHex =
        normalized.toRadixString(16).toUpperCase().padLeft(16, '0');

    final BigInt val = BigInt.tryParse(cleanHex, radix: 16) ?? BigInt.zero;
    final ByteData view = ByteData.sublistView(npdm);

    // 64-bit Little Endian Title ID
    BigInt temp = val;
    final List<int> tidBytes = List.filled(8, 0);
    for (int i = 0; i < 8; i++) {
      tidBytes[i] = (temp & BigInt.from(0xFF)).toInt();
      temp = temp >> 8;
    }

    // 1. Patch ACID Title ID Range Min & Max (offset 0x290 and 0x298)
    for (int i = 0; i < 8; i++) {
      view.setUint8(0x290 + i, tidBytes[i]);
      view.setUint8(0x298 + i, tidBytes[i]);
    }

    // 2. Patch ACI0 Title ID (offset 0x350)
    for (int i = 0; i < 8; i++) {
      view.setUint8(0x350 + i, tidBytes[i]);
    }

    return npdm;
  }

  /// Generates the ExeFS PFS0 binary container containing:
  /// - 'main': Compiled ARM64 NSO0 homebrew forwarder executable
  /// - 'main.npdm': Nintendo Process Descriptor Meta patched with config Title ID
  static Uint8List buildExeFs(ForwarderConfig config) {
    final Uint8List mainBytes = getMainBinary();
    final Uint8List npdmBytes = getPatchedNpdm(config.id);

    final List<Pfs0File> files = [
      Pfs0File(name: 'main', data: mainBytes),
      Pfs0File(name: 'main.npdm', data: npdmBytes),
    ];

    return Pfs0Builder.build(files);
  }

  /// Generates the Program RomFS binary containing 'nextNroPath' and 'nextArgv'.
  static Uint8List buildProgramRomFs(ForwarderConfig config) {
    return RomfsBuilder.buildProgramRomfs(
      nroPath: config.nroPath,
      romPath: (config.isRetroArch && config.romPath.isNotEmpty)
          ? config.romPath
          : null,
    );
  }
}
